<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UNIFCO | Inbox</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><style>:root{--navy:#06275c;--red:#e20b24;--line:#dfe5ee;--bg:#f5f8fb;--muted:#6d7b90}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:"Cairo",Tahoma,Arial,sans-serif;color:#10233e}.page{min-height:100vh;display:grid;grid-template-columns:220px 1fr}.side{background:linear-gradient(180deg,#06275c,#042252);color:#fff;padding:18px 12px}.customer-logo{height:105px;background:#fff;border-radius:14px;display:flex;align-items:center;justify-content:center;padding:12px;margin-bottom:14px}.customer-logo img{max-width:100%;max-height:82px;object-fit:contain}.fallback{color:var(--navy);font-weight:900;text-align:center}.side a{display:block;color:#fff;text-decoration:none;padding:10px 12px;border-radius:8px;font-size:12px}.side a:hover,.side a.active{background:#ffffff18}.main{padding:22px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.top a{text-decoration:none;color:var(--navy);font-weight:800;font-size:12px}.layout{display:grid;grid-template-columns:320px 1fr;gap:14px}.panel{background:#fff;border:1px solid var(--line);border-radius:13px;overflow:hidden}.panel h2{margin:0;padding:17px;border-bottom:1px solid var(--line);font-size:16px;color:var(--navy)}.new{padding:14px;border-bottom:1px solid var(--line)}input,textarea{width:100%;border:1px solid #ccd6e2;border-radius:8px;padding:9px;font:inherit;margin-bottom:8px}textarea{min-height:85px}.btn{border:0;background:var(--red);color:#fff;border-radius:8px;padding:9px 14px;font:inherit;font-size:11px;font-weight:900;cursor:pointer}.threads{max-height:620px;overflow:auto}.thread{display:block;padding:13px 15px;border-bottom:1px solid #edf1f5;text-decoration:none;color:#14243a}.thread.active{background:#f0f5fb}.thread b{display:block;font-size:11px}.thread small{color:var(--muted);font-size:9px}.chat{display:flex;flex-direction:column;min-height:620px}.chat-head{padding:16px;border-bottom:1px solid var(--line)}.chat-head b{color:var(--navy)}.messages{flex:1;padding:18px;display:flex;flex-direction:column;gap:10px;background:#fafcff}.msg{max-width:72%;padding:10px 12px;border-radius:12px;font-size:11px;line-height:1.8}.msg.customer{align-self:flex-start;background:#e9f1fb;color:#0c315f}.msg.unifco{align-self:flex-end;background:#06275c;color:#fff}.msg small{display:block;opacity:.65;margin-top:4px;font-size:8px}.reply{padding:14px;border-top:1px solid var(--line)}.notice{background:#eaf8f0;color:#176a43;padding:9px 12px;border-radius:8px;margin-bottom:12px;font-size:11px}@media(max-width:820px){.page{grid-template-columns:1fr}.side{display:none}.layout{grid-template-columns:1fr}.main{padding:12px}.chat{min-height:500px}}</style></head><body><div class="page"><aside class="side"><div class="customer-logo">@if($customer->logo_path)<img src="{{ asset('storage/'.$customer->logo_path) }}" alt="{{ $customer->name }}">@else<div class="fallback">{{ $customer->name }}</div>@endif</div><a href="{{ route('customer.portal') }}">Dashboard</a><a class="active" href="{{ route('customer.inbox') }}">✉ Inbox</a><a href="{{ route('customer.profile.edit') }}">Profile</a></aside><main class="main"><div class="top"><div><h1 style="margin:0;font-size:23px">Inbox</h1><small style="color:var(--muted)">رسائل العميل مع فريق UNIFCO</small></div><a href="{{ route('customer.portal') }}">العودة إلى {{ $customer->name }}</a></div>@if(session('status'))<div class="notice">{{ session('status') }}</div>@endif<div class="layout"><section class="panel"><h2>المحادثات</h2><form class="new" method="POST" action="{{ route('customer.inbox.start') }}">@csrf<input name="subject" placeholder="عنوان الرسالة" required><textarea name="body" placeholder="اكتب رسالتك إلى UNIFCO" required></textarea><button class="btn">رسالة جديدة</button></form><div class="threads">@forelse($conversations as $c)<a class="thread {{ $activeConversation && $activeConversation->id===$c->id?'active':'' }}" href="{{ route('customer.inbox',['conversation'=>$c->id]) }}"><b>{{ $c->subject }}</b><small>{{ $c->last_message_at ?: $c->created_at }}</small></a>@empty<div style="padding:18px;color:var(--muted);font-size:11px">لا توجد محادثات بعد.</div>@endforelse</div></section><section class="panel chat">@if($activeConversation)<div class="chat-head"><b>{{ $activeConversation->subject }}</b></div><div class="messages">@foreach($messages as $m)<div class="msg {{ strtolower($m->sender_side) }}">{{ $m->body }}<small>{{ $m->created_at }}</small></div>@endforeach</div><form class="reply" method="POST" action="{{ route('customer.inbox.reply',$activeConversation->id) }}">@csrf<textarea name="body" placeholder="اكتب ردك..." required></textarea><button class="btn">إرسال</button></form>@else<div style="padding:30px;color:var(--muted)">اختر محادثة أو ابدأ رسالة جديدة.</div>@endif</section></div></main></div></body></html>